package local.lito381.server;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Actual scalar operations, no life/Hub/PC fixture; original owner/queue ports are checked by independent inverse. */
public final class SourceDamageCapacityPlan {
 static int cases;static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);cases++;}
 public static void main(String[]args)throws Exception{
  var work=new AtomicLong(7000);var damage=new AtomicLong();check(NativeSourceDamageCapacity.empty(damage),"fresh damage domain is empty despite AI work");check(NativeSourcePendingAdmission.reserve(damage,2)&&damage.get()==1&&work.get()==7000,"AI work cannot consume a queued damage slot");check(NativeSourcePendingAdmission.reserve(damage,2)&&!NativeSourcePendingAdmission.reserve(damage,2),"PC/NPC primitive reservations share exact damage cap");NativeSourceDamageCapacity.releaseCounter(damage,1);check(damage.get()==1&&work.get()==7000,"dequeue releases damage independently of original work accounting");NativeSourceDamageCapacity.releaseCounter(damage,1);check(NativeSourceDamageCapacity.empty(damage),"all original queued credits can settle before HP side effects finish");
  boolean duplicate=false;try{NativeSourceDamageCapacity.releaseCounter(damage,1);}catch(IllegalStateException expected){duplicate=true;}check(duplicate&&damage.get()==0,"invalid duplicate release cannot make damage ledger negative");boolean negative=false;try{NativeSourceDamageCapacity.releaseCounter(damage,-1);}catch(IllegalStateException expected){negative=true;}check(negative&&damage.get()==0,"negative drop count cannot manufacture capacity credits");NativeSourceDamageCapacity.releaseCounter(damage,0);check(damage.get()==0,"empty clear does not change credit");
  for(int i=0;i<17;i++)NativeSourcePendingAdmission.reserve(damage,17);check(damage.get()==17,"bounded pending damage may fill its own domain");NativeSourceDamageCapacity.releaseCounter(damage,16);check(damage.get()==1,"tail drop preserves the remaining queued credit");NativeSourceDamageCapacity.releaseCounter(damage,1);check(damage.get()==0&&work.get()==7000,"all queued damage drops leave AI accounting unchanged");
  var deque=new ArrayDeque<Object>();NativeSourcePendingAdmission.reserve(damage,1);boolean failed=false;try{NativeSourcePendingAdmission.add(deque,null,damage);}catch(NullPointerException expected){failed=true;}check(failed&&damage.get()==0&&work.get()==7000,"failed PC publication returns damage reservation only");
  var counters=List.of(new AtomicLong(),new AtomicLong());NativeSourcePendingAdmission.reserve(counters.get(0),1);check(!NativeSourceDamageCapacity.empty(counters.get(0))&&NativeSourceDamageCapacity.empty(counters.get(1)),"independent original application counters do not share a registry");NativeSourceDamageCapacity.releaseCounter(counters.get(0),1);
  var start=new CountDownLatch(1);var error=new AtomicReference<Throwable>();var threads=new ArrayList<Thread>();for(int k=0;k<8;k++){var thread=new Thread(()->{try{start.await();for(int n=0;n<2000;n++){while(!NativeSourcePendingAdmission.reserve(damage,8))Thread.yield();NativeSourceDamageCapacity.releaseCounter(damage,1);}}catch(Throwable failure){error.compareAndSet(null,failure);}},"pure-damage-ledger-"+k);threads.add(thread);thread.start();}start.countDown();for(var thread:threads)thread.join(10000);check(error.get()==null&&threads.stream().noneMatch(Thread::isAlive)&&damage.get()==0,"concurrent primitive reserve/release balances exactly");check(work.get()==7000,"concurrent damage operations never mutate the AI fixture counter");
  check(!NativeSourceDamageCapacity.offer(null,null,null),"missing queue/event cannot create an original application lifetime");
  if(cases!=16)throw new AssertionError(cases);System.out.println("PASS16 damage-domain isolation/bounds/dequeue/drop/failed publication/concurrency scalar contracts; no life/Hub/PC/socket/SQL/BATTLE fixture");
 }
}
